import { Link } from "react-router-dom";

function ChildCard({ child }) {
  return (
    <Link to={`/child/${child.id}`} style={{ textDecoration: "none", color: "inherit" }}>
      <div style={{
        border: "1px solid #ccc",
        padding: "15px",
        margin: "10px",
        borderRadius: "10px"
      }}>
        <h3>{child.name}</h3>
        <p>Age: {child.age}</p>
        <p>Class: {child.class}</p>
      </div>
    </Link>
  );
}

export default ChildCard;
